do $c$ declare n_bad_sec int; n_bad_zone int; n int; begin
  select count(*) into n from _sz_new;
  select count(*) into n_bad_sec from _sz_new x where not exists (select 1 from public.sections s where s.id = x.section_id);
  select count(*) into n_bad_zone from _sz_new x where not exists (select 1 from public.warning_zones w where w.zone_code = x.zone_code);
  if n <> 1352 or n_bad_sec > 0 or n_bad_zone > 0 then raise exception '111: 줄 %개, 없는 구간 %개, 없는 구역 %개 — 중단', n, n_bad_sec, n_bad_zone; end if;
end $c$;

delete from public.section_zones;
insert into public.section_zones (section_id, zone_code, km) select section_id, zone_code, km from _sz_new;

-- 요청은 자기 관할만
do $p$
declare d text := pg_get_functiondef('public.zone_request_create(text,text,text,text)'::regprocedure);
        a text := 'if r = ''admin'' then raise exception ''관리자는 요청 없이 바로 바꿉니다'' using errcode = ''22023''; end if;';
        b text := a || chr(10) ||
  '  if r not in (''branch'', ''hq'') then raise exception ''특보구역 조정 요청은 지사·본부 아이디만 할 수 있습니다'' using errcode = ''42501''; end if;' || chr(10) ||
  '  if r = ''branch'' and p_branch is distinct from (select p.branch_id from public.profiles p where p.id = (select auth.uid())) then' || chr(10) ||
  '    raise exception ''자기 지사만 요청할 수 있습니다'' using errcode = ''42501''; end if;' || chr(10) ||
  '  if r = ''hq'' and not exists (select 1 from public.branches b join public.profiles p on p.id = (select auth.uid()) where b.id = p_branch and b.hq_id = p.hq_id) then' || chr(10) ||
  '    raise exception ''자기 본부의 지사만 요청할 수 있습니다'' using errcode = ''42501''; end if;';
begin
  if (length(d) - length(replace(d, a, ''))) <> length(a) then raise exception '111: zone_request_create 바꿀 곳이 한 군데가 아님'; end if;
  execute replace(d, a, b);
end $p$;

commit;
